mapper.select:
select count(*) from "h_check_inout"
 where username = #{username}
   and inout_type = #{inoutType}
   and check_in >= current_date

mapper.delete:
delete from "h_pt_schedule"
 where schedule_id = #{scheduleId}
   and trainer_id = #{trainerId}

mapper.select:
select count(*) as "total"
from "h_check_inout"
where gym_id = #{gymId}
